{"file_path":"src/lexer.js","content":"/**
 * Character-level scanning for a single directive line: names, strings,
 * bare tokens (booleans/numbers) and the composite value forms (arrays and
 * inline tables). Every directive fits on one physical line, so a Cursor
 * never needs to look past the end of the string it was built from.
 */

export class Cursor {
  constructor(line, lineNo) {
    this.line = line
    this.lineNo = lineNo
    this.pos = 0
  }

  get len() {
    return this.line.length
  }

  peek() {
    return this.pos < this.len ? this.line[this.pos] : undefined
  }

  atEnd() {
    return this.pos >= this.len
  }

  skipSpaces() {
    while (this.pos < this.len && (this.line[this.pos] === ' ' || this.line[this.pos] === '\t')) {
      this.pos++
    }
  }

  // Call after skipSpaces(): a top-level # or ; ends the line right here.
  checkComment() {
    const c = this.peek()
    if (c === '#' || c === ';') this.pos = this.len
  }

  skipSpacesAndComment() {
    this.skipSpaces()
    this.checkComment()
  }

  err(reason) {
    const e = new Error(reason)
    e.lineNo = this.lineNo
    throw e
  }
}

function isBareNameChar(c) {
  return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c === '_' || c === '-'
}

export function parseName(cur) {
  const c = cur.peek()
  if (c === '"') return parseBasicString(cur)
  if (c === "'") return parseLiteralString(cur)
  if (c !== undefined && isBareNameChar(c)) {
    const start = cur.pos
    while (!cur.atEnd() && isBareNameChar(cur.line[cur.pos])) cur.pos++
    return cur.line.slice(start, cur.pos)
  }
  cur.err('expected a name')
}

export function parseDottedName(cur) {
  const segs = [parseName(cur)]
  while (true) {
    cur.skipSpaces()
    if (cur.peek() === '.') {
      cur.pos++
      cur.skipSpaces()
      segs.push(parseName(cur))
    } else {
      break
    }
  }
  return segs
}

export function parseBasicString(cur) {
  cur.pos++ // opening quote
  let out = ''
  while (true) {
    if (cur.atEnd()) cur.err('unterminated string')
    const c = cur.line[cur.pos]
    if (c === '"') {
      cur.pos++
      return out
    }
    if (c === '\\') {
      cur.pos++
      if (cur.atEnd()) cur.err('unterminated string')
      const e = cur.line[cur.pos]
      switch (e) {
        case '"':
          out += '"'
          cur.pos++
          break
        case '\\':
          out += '\\'
          cur.pos++
          break
        case 'n':
          out += '\n'
          cur.pos++
          break
        case 't':
          out += '\t'
          cur.pos++
          break
        case 'r':
          out += '\r'
          cur.pos++
          break
        case '0':
          out += '\0'
          cur.pos++
          break
        case 'u': {
          const hex = cur.line.slice(cur.pos + 1, cur.pos + 5)
          if (hex.length < 4) cur.err('unterminated string')
          if (!/^[0-9A-Fa-f]{4}$/.test(hex)) cur.err('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          cur.pos += 5
          break
        }
        default:
          cur.err(`invalid escape \\${e}`)
      }
    } else {
      out += c
      cur.pos++
    }
  }
