export function parseLiteralString(cur) {
  cur.pos++ // opening quote
  const start = cur.pos
  while (true) {
    if (cur.atEnd()) cur.err('unterminated string')
    if (cur.line[cur.pos] === "'") {
      const s = cur.line.slice(start, cur.pos)
      cur.pos++
      return s
    }
    cur.pos++
  }
