const DIGIT_RUN = '[0-9]+(?:_[0-9]+)*'
const INT_RE = new RegExp(`^[+-]?${DIGIT_RUN}$`)
const FLOAT_RE = new RegExp(`^[+-]?${DIGIT_RUN}(?:\\.${DIGIT_RUN})?(?:[eE][+-]?${DIGIT_RUN})?$`)

function interpretBareValue(text, cur) {
  if (text === 'true') return { type: 'boolean', value: true }
  if (text === 'false') return { type: 'boolean', value: false }
  if (INT_RE.test(text)) {
    const clean = text.replace(/_/g, '').replace(/^\+/, '')
    return { type: 'integer', value: BigInt(clean) }
  }
  if (/[.eE]/.test(text) && FLOAT_RE.test(text)) {
    const clean = text.replace(/_/g, '')
    return { type: 'float', value: Number(clean) }
  }
  cur.err(`invalid value ${text}`)
}

function isTokenBoundary(ch) {
  return ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}'
}

