  cur.pos++ // consume [
  const items = []
  cur.skipSpaces()
  cur.checkComment()
  if (cur.atEnd()) cur.err('unterminated array')
  if (cur.peek() === ']') {
    cur.pos++
    return { type: 'array', items }
  }
  while (true) {
    const v = parseValue(cur, path)
    items.push(v)
    cur.skipSpaces()
    cur.checkComment()
    if (cur.atEnd()) cur.err('unterminated array')
    const c = cur.peek()
    if (c === ',') {
      cur.pos++
      cur.skipSpaces()
      cur.checkComment()
      if (cur.atEnd()) cur.err('unterminated array')
      if (cur.peek() === ']') {
        cur.pos++
        return { type: 'array', items }
      }
      continue
    }
    if (c === ']') {
      cur.pos++
      return { type: 'array', items }
    }
    cur.err('unterminated array')
  }
}

