  if (cur.peek() === '}') {
    cur.pos++
    return table
  }
  while (true) {
    const segs = parseDottedName(cur)
    cur.skipSpaces()
    cur.checkComment()
    if (cur.atEnd() || cur.peek() !== '=') cur.err('expected = in an inline table')
    cur.pos++
    cur.skipSpaces()
    cur.checkComment()
    const valuePath = [...path, ...segs.map((name) => ({ kind: 'key', name }))]
    const value = parseValue(cur, valuePath)
    assignInto(table, path, segs, value, cur)
    cur.skipSpaces()
    cur.checkComment()
    if (cur.atEnd()) cur.err('unterminated inline table')
    const c = cur.peek()
    if (c === ',') {
      cur.pos++
      cur.skipSpaces()
      cur.checkComment()
      if (cur.atEnd()) cur.err('unterminated inline table')
      continue
    }
    if (c === '}') {
      cur.pos++
      return table
    }
    cur.err('unterminated inline table')
  }
}

