  let s = ''
  for (const t of path) {
    if (t.kind === 'index') s += `[${t.i}]`
    else s += (s.length ? '.' : '') + t.name
  }
  return s
}

function stepInto(table, seg, path, cur) {
  let node = table.map.get(seg)
  if (node === undefined) {
    node = { type: 'table', map: new Map(), headerDefined: false }
    table.map.set(seg, node)
    return node
  }
  if (node.type === 'table') return node
  if (node.type === 'array-of-tables') return node.tables[node.tables.length - 1]
  cur.err(`${pathToString(path)} is not a table`)
}

function assignInto(table, basePath, segs, value, cur) {
  let t = table
  const path = [...basePath]
  for (let i = 0; i < segs.length - 1; i++) {
    path.push({ kind: 'key', name: segs[i] })
    t = stepInto(t, segs[i], path, cur)
  }
  const last = segs[segs.length - 1]
  path.push({ kind: 'key', name: last })
  if (t.map.has(last)) cur.err(`key ${pathToString(path)} is defined twice`)
  t.map.set(last, value)
}

export { pathToString, stepInto, assignInto }
