function codePoints(s) {
  return Array.from(s).map((ch) => ch.codePointAt(0))
}

function cmpCodePoint(a, b) {
  const ca = codePoints(a)
  const cb = codePoints(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    if (ca[i] !== cb[i]) return ca[i] - cb[i]
  }
  return ca.length - cb.length
}

function sortedKeys(table) {
  return [...table.map.keys()].sort(cmpCodePoint)
}

function pad(n) {
  return '  '.repeat(n)
}

function jsonValue(node, indent) {
  switch (node.type) {
    case 'table':
      return jsonTable(node, indent)
    case 'array-of-tables':
      return jsonArray(node.tables, indent)
    case 'array':
      return jsonArray(node.items, indent)
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

function jsonTable(node, indent) {
  const keys = sortedKeys(node)
  if (keys.length === 0) return '{}'
  const inner = keys
    .map((k) => `${pad(indent + 1)}${JSON.stringify(k)}: ${jsonValue(node.map.get(k), indent + 1)}`)
    .join(',\n')
  return `{\n${inner}\n${pad(indent)}}`
}

