  if (items.length === 0) return '[]'
  const inner = items.map((v) => `${pad(indent + 1)}${jsonValue(v, indent + 1)}`).join(',\n')
  return `[\n${inner}\n${pad(indent)}]`
}

export function toJson(root) {
  return jsonValue(root, 0) + '\n'
}

function typeName(node) {
  switch (node.type) {
    case 'table':
      return 'table'
    case 'array-of-tables':
      return 'array'
    case 'array':
      return 'array'
    default:
