    const child = root.map.get(k)
    const p = [{ kind: 'key', name: k }]
    lines.push(`${formatPath(p)} ${typeName(child)}`)
    walk(child, p, lines)
  }
  return lines.length ? lines.join('\n') + '\n' : ''
}
