/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { parseDocument } from './document.js'
import { toJson, toKeys } from './output.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'json' && mode !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exitCode = 2
    return
  }

  const input = await readStdin()

  let root
  try {
    root = parseDocument(input)
  } catch (e) {
    if (e && typeof e.lineNo === 'number') {
      process.stderr.write(`error: line ${e.lineNo}: ${e.message}\n`)
      process.exitCode = 2
      return
    }
    throw e
  }

  const out = mode === 'json' ? toJson(root) : toKeys(root)
  await new Promise((resolve) => process.stdout.write(out, resolve))
  process.exitCode = 0
}

main().catch((e) => {
  process.stderr.write(`error: ${e && e.message ? e.message : String(e)}\n`)
  process.exitCode = 2
})
"}

